16.query:
fetch logs
| filter project == $Me
| fieldsAdd source = if(isNotNull(flow.type), "NetFlow",
    else: if(isNotNull(log.file.name), concat("File: ", log.file.name),
    else: if(isNotNull(appname), concat("Syslog: ", appname), else: "Other")))
| summarize records = count(), by: { source }
| sort records desc

